{
  "dataset_meaning": "Telecom customer records with usage, account, and demographic attributes for churn prediction. Unique record keys and suspiciously predictive fields warrant leakage checks; validate on a future or otherwise deployment-representative split.",
  "target_meaning": "Churn is a binary indicator of whether a telecom customer churned; class 1 represents 15.7% of records.",
  "row_meaning": "One telecom customer record, apparently one row per unique customer key.",
  "column_roles": [
    {
      "column": "record_key",
      "role": "identifier",
      "meaning_guess": "Unique customer or record key; unusually predictive, so exclude from modeling."
    },
    {
      "column": "Call_Failure",
      "role": "pre_outcome_feature",
      "meaning_guess": "Count of failed calls before the churn outcome."
    },
    {
      "column": "Complains",
      "role": "pre_outcome_feature",
      "meaning_guess": "Whether the customer filed a complaint."
    },
    {
      "column": "Subscription_Length",
      "role": "pre_outcome_feature",
      "meaning_guess": "Length of the customer's subscription."
    },
    {
      "column": "Charge_Amount",
      "role": "pre_outcome_feature",
      "meaning_guess": "Customer's charge level or amount."
    },
    {
      "column": "Seconds_of_Use",
      "role": "pre_outcome_feature",
      "meaning_guess": "Total call usage duration in seconds."
    },
    {
      "column": "Frequency_of_use",
      "role": "pre_outcome_feature",
      "meaning_guess": "Frequency of customer service or call usage."
    },
    {
      "column": "Frequency_of_SMS",
      "role": "pre_outcome_feature",
      "meaning_guess": "Frequency of SMS usage."
    },
    {
      "column": "Distinct_Called_Numbers",
      "role": "pre_outcome_feature",
      "meaning_guess": "Count of distinct numbers called."
    },
    {
      "column": "Age_Group",
      "role": "pre_outcome_feature",
      "meaning_guess": "Categorized customer age."
    },
    {
      "column": "Tariff_Plan",
      "role": "pre_outcome_feature",
      "meaning_guess": "Customer's tariff or pricing plan."
    },
    {
      "column": "Status",
      "role": "post_outcome",
      "meaning_guess": "Likely active/inactive account status; may reveal churn."
    },
    {
      "column": "Age",
      "role": "pre_outcome_feature",
      "meaning_guess": "Customer age or age-band value; overlaps Age_Group."
    },
    {
      "column": "Customer_Value",
      "role": "pre_outcome_feature",
      "meaning_guess": "Estimated customer value, likely based on account activity."
    },
    {
      "column": "segment_outcome_rate",
      "role": "target_derived",
      "meaning_guess": "Outcome rate for a segment; likely computed using churn labels."
    },
    {
      "column": "load_weekday",
      "role": "artifact",
      "meaning_guess": "Likely data-loading weekday metadata, not customer behavior."
    },
    {
      "column": "deactivation_reason",
      "role": "post_outcome",
      "meaning_guess": "Reason for deactivation; available only after churn."
    }
  ]
}

{
  "proposed_features": [
    {
      "name": "avg_seconds_per_call",
      "op": "ratio",
      "inputs": ["Seconds_of_Use", "Frequency_of_use"],
      "semantic_rationale": "Estimates average call duration from usage aggregated during the observation window.",
      "statistical_rationale": "Normalizes total call time for call volume, potentially distinguishing customers with similar total usage but different calling patterns. Handle zero call counts explicitly.",
      "leakage_assessment": "none",
      "business_interpretation": "A customer's typical call length may help characterize their engagement and service needs."
    },
    {
      "name": "failures_per_call",
      "op": "ratio",
      "inputs": ["Call_Failure", "Frequency_of_use"],
      "semantic_rationale": "Relates the recorded number of call failures to call frequency during the observation window.",
      "statistical_rationale": "Normalizes failure counts for usage volume, which may reveal service-quality differences beyond raw counts. Handle zero call counts explicitly; the ratio is only an approximation if failures are not measured on the same basis as calls.",
      "leakage_assessment": "none",
      "business_interpretation": "A higher value may indicate a customer experiencing more failed calls relative to their usage."
    },
    {
      "name": "number_diversity_per_call",
      "op": "ratio",
      "inputs": ["Distinct_Called_Numbers", "Frequency_of_use"],
      "semantic_rationale": "Measures the number of distinct numbers called relative to total call frequency.",
      "statistical_rationale": "Normalizes calling diversity by call volume and may distinguish broad from concentrated calling patterns. Handle zero call counts explicitly.",
      "leakage_assessment": "none",
      "business_interpretation": "A higher value suggests calls are spread across more distinct numbers, rather than concentrated among a few."
    },
    {
      "name": "sms_per_call",
      "op": "ratio",
      "inputs": ["Frequency_of_SMS", "Frequency_of_use"],
      "semantic_rationale": "Compares text-message frequency with call frequency over the observation window.",
      "statistical_rationale": "Captures communication-channel mix that is not represented by either activity count alone. Handle zero call counts explicitly.",
      "leakage_assessment": "none",
      "business_interpretation": "A higher value indicates relatively greater SMS use compared with voice-call activity."
    },
    {
      "name": "log_customer_value",
      "op": "log1p",
      "inputs": ["Customer_Value"],
      "semantic_rationale": "Transforms the recorded customer value while preserving its ordering.",
      "statistical_rationale": "The profile shows a wide range and a high maximum relative to the median; a log transform can reduce skew and limit the influence of extreme values.",
      "leakage_assessment": "possible",
      "business_interpretation": "Provides a compressed view of customer value, making differences among lower-value customers more distinguishable without letting extreme values dominate."
    }
  ],
  "candidate_judgements": {
    "cand_seconds_per_call": {
      "decision": "accept",
      "reason": "This is a meaningful normalization of two usage measures aggregated over the pre-outcome observation window. Its value is semantic, not merely its univariate AUC; handle customers with zero calls."
    },
    "cand_failure_rate": {
      "decision": "accept",
      "reason": "Relating failures to call volume can distinguish service-quality experience from overall usage. Confirm the recipe uses only pre-outcome columns and handles zero call volume; the name may overstate precision if failures and calls are not measured on comparable bases."
    },
    "cand_key_log": {
      "decision": "reject",
      "reason": "record_key is an internal warehouse identifier, not a customer behavior or actionable signal. Its very high association is suspicious and may reflect ordering or extraction artifacts; transforming it does not make it a valid predictor."
    },
    "cand_post_flag": {
      "decision": "reject",
      "reason": "deactivation_reason is recorded when a line is deactivated and is post-outcome information. Its strong association is consistent with direct outcome leakage."
    },
    "cand_friday": {
      "decision": "reject",
      "reason": "load_weekday records when the warehouse row was loaded, not a customer behavior measured in the observation window. The association may reflect a data-pipeline artifact and is not a sound predictive feature."
    },
    "cand_target_mean": {
      "decision": "reject",
      "reason": "The feature is computed using the target on the full table, including evaluation rows. This leaks evaluation outcomes into feature construction; target-derived encoding would require training-fold-only computation with appropriate out-of-fold handling."
    }
  }
}

{
  "proposed_features": [
    {
      "name": "x1_log1p",
      "op": "log1p",
      "inputs": ["x1"],
      "semantic_rationale": "Preserves the ordering of this nonnegative measurement while representing its scale more compactly; its real-world meaning is not identifiable from the profile.",
      "statistical_rationale": "x1 spans 0 to 2165 with a median of 229.9. Log compression may reduce the influence of large values and let a model capture nonlinear effects.",
      "leakage_assessment": "none",
      "business_interpretation": "A compressed representation of x1's magnitude."
    },
    {
      "name": "x15_log1p",
      "op": "log1p",
      "inputs": ["x15"],
      "semantic_rationale": "Provides a compressed scale for a nonnegative quantity without assuming what it measures.",
      "statistical_rationale": "x15 has a wide range and a median far below its maximum, so a log transform may make relative differences more useful than raw differences.",
      "leakage_assessment": "none",
      "business_interpretation": "A compressed representation of x15's magnitude."
    },
    {
      "name": "x16_log1p",
      "op": "log1p",
      "inputs": ["x16"],
      "semantic_rationale": "Represents the magnitude of x16 on a compressed scale; the profile does not establish its domain meaning.",
      "statistical_rationale": "The nonnegative feature ranges from 0 to 522 with a median of 21, making nonlinear scaling potentially useful.",
      "leakage_assessment": "none",
      "business_interpretation": "A compressed representation of x16's magnitude."
    },
    {
      "name": "x10_is_zero",
      "op": "is_zero",
      "inputs": ["x10"],
      "semantic_rationale": "Separates absence or zero from positive values without assuming what x10 counts or measures.",
      "statistical_rationale": "x10 has a median of zero and a maximum of 10, suggesting a potentially meaningful zero-versus-nonzero distinction.",
      "leakage_assessment": "none",
      "business_interpretation": "Indicates whether x10 is zero."
    },
    {
      "name": "x13_is_zero",
      "op": "is_zero",
      "inputs": ["x13"],
      "semantic_rationale": "Makes the distinction between a zero value and a positive value explicit.",
      "statistical_rationale": "x13 includes zero and has a low-valued range, so a zero indicator may capture a threshold effect that a continuous representation misses.",
      "leakage_assessment": "none",
      "business_interpretation": "Indicates whether x13 is zero."
    }
  ],
  "candidate_judgements": {
    "cand_seconds_per_call": {
      "decision": "reject",
      "reason": "The profile does not identify which columns define seconds or calls, so the recipe and denominator cannot be verified; accepting it could introduce an invalid or outcome-timed feature."
    },
    "cand_failure_rate": {
      "decision": "reject",
      "reason": "No columns are identified as failures or total attempts, so the rate cannot be validated or checked for leakage from post-outcome information."
    },
    "cand_key_log": {
      "decision": "reject",
      "reason": "x11 has a unique value for every row and a very strong target association, consistent with an identifier or ordered key. Transforming it does not remove that risk."
    },
    "cand_post_flag": {
      "decision": "reject",
      "reason": "x7 has an extreme target association and is listed as an artifact or leakage column. A flag derived from it would preserve that concern."
    },
    "cand_friday": {
      "decision": "accept",
      "reason": "x14 is a weekday category, and a Friday indicator is a simple, interpretable encoding of an existing feature. The profile gives no evidence that it is post-outcome or an identifier."
    },
    "cand_target_mean": {
      "decision": "reject",
      "reason": "It is computed using target values from the full table, including evaluation rows. This leaks target information and would also require leakage-safe out-of-fold construction even if used as a training-only encoding."
    }
  }
}

{
  "proposed_features": [
    {
      "name": "log1p_seconds_of_use",
      "op": "log1p",
      "inputs": ["Seconds_of_Use"],
      "semantic_rationale": "Compresses the scale of total usage while preserving its ordering.",
      "statistical_rationale": "Usage is highly variable; a log transform may reduce skew and let a model represent differences among lower-usage customers more effectively.",
      "leakage_assessment": "possible",
      "business_interpretation": "Represents usage intensity on a scale less dominated by very high-use customers. The measurement window is not specified."
    },
    {
      "name": "log1p_customer_value",
      "op": "log1p",
      "inputs": ["Customer_Value"],
      "semantic_rationale": "Transforms the customer value measure without changing its ordering.",
      "statistical_rationale": "The wide range and high number of distinct values suggest a skewed measure; compression may limit the influence of extreme values.",
      "leakage_assessment": "possible",
      "business_interpretation": "Captures customer value with diminishing scale for very large values. The definition and measurement timing of Customer_Value are not provided."
    },
    {
      "name": "sms_to_use_ratio",
      "op": "ratio",
      "inputs": ["Frequency_of_SMS", "Frequency_of_use"],
      "semantic_rationale": "Compares SMS activity with general usage activity, representing the customer’s observed communication mix.",
      "statistical_rationale": "A normalized ratio can distinguish customers with similar overall activity but different SMS intensity. Handle zero usage denominators explicitly.",
      "leakage_assessment": "possible",
      "business_interpretation": "Indicates how SMS-heavy a customer’s activity is relative to their usage. The observation window is unspecified."
    },
    {
      "name": "uses_per_distinct_number",
      "op": "ratio",
      "inputs": ["Frequency_of_use", "Distinct_Called_Numbers"],
      "semantic_rationale": "Relates usage frequency to the number of distinct called numbers, approximating concentration of calling activity.",
      "statistical_rationale": "Normalization may separate frequent callers with concentrated contacts from those whose activity is spread across many contacts. Handle zero denominators explicitly.",
      "leakage_assessment": "possible",
      "business_interpretation": "Higher values indicate more usage per distinct number called. The observation window is unspecified."
    },
    {
      "name": "zero_sms_activity",
      "op": "is_zero",
      "inputs": ["Frequency_of_SMS"],
      "semantic_rationale": "Marks customers with no recorded SMS activity.",
      "statistical_rationale": "A zero-activity indicator can capture a discontinuity that a numeric activity count alone may not represent well.",
      "leakage_assessment": "possible",
      "business_interpretation": "Distinguishes customers with no SMS use from those with any SMS use. The observation window is unspecified."
    }
  ],
  "candidate_judgements": {
    "cand_seconds_per_call": {
      "decision": "accept",
      "reason": "Seconds_of_Use divided by Frequency_of_use has a plausible interpretation as average usage per use and may capture intensity beyond total activity. Guard against zero denominators; the observation window is unspecified."
    },
    "cand_failure_rate": {
      "decision": "accept",
      "reason": "If defined as Call_Failure divided by Frequency_of_use, it is a plausible normalized failure measure that may distinguish failure burden from overall usage. Guard against zero denominators and verify that the counts use compatible definitions and windows."
    },
    "cand_key_log": {
      "decision": "reject",
      "reason": "record_key is a unique identifier, not a customer behavior measure. Its very high association is suspicious and could reflect ordering, partition, or other accidental target encoding; logging it does not make it a valid predictor."
    },
    "cand_post_flag": {
      "decision": "reject",
      "reason": "deactivation_reason appears to describe a post-churn outcome. Whether it is set would directly reveal information unavailable at prediction time."
    },
    "cand_friday": {
      "decision": "reject",
      "reason": "load_weekday is identified as an artifact column, and the event whose weekday it records is unspecified. Its association does not establish that it is a valid, pre-outcome customer feature."
    },
    "cand_target_mean": {
      "decision": "reject",
      "reason": "The encoding uses target values from the full table, including evaluation rows, so it leaks evaluation labels. A carefully cross-fitted encoding using training data only would be a different candidate."
    }
  }
}

{
  "proposed_features": [
    {
      "name": "seconds_per_use",
      "op": "ratio",
      "inputs": ["Seconds_of_Use", "Frequency_of_use"],
      "semantic_rationale": "Approximates average call duration per use, complementing total usage volume.",
      "statistical_rationale": "Normalizing total seconds by usage frequency may distinguish many short calls from fewer long calls; check for zero denominators.",
      "leakage_assessment": "none",
      "business_interpretation": "A change in typical call duration may identify shifts in customer engagement."
    },
    {
      "name": "sms_to_call_frequency",
      "op": "ratio",
      "inputs": ["Frequency_of_SMS", "Frequency_of_use"],
      "semantic_rationale": "Compares SMS activity with call-use frequency as a measure of communication-channel preference.",
      "statistical_rationale": "A ratio can capture differences in communication mix that raw activity counts do not; check for zero denominators.",
      "leakage_assessment": "none",
      "business_interpretation": "Customers with a changing balance of SMS and call activity may warrant different retention messaging."
    },
    {
      "name": "distinct_numbers_per_use",
      "op": "ratio",
      "inputs": ["Distinct_Called_Numbers", "Frequency_of_use"],
      "semantic_rationale": "Measures the breadth of called contacts relative to call-use frequency.",
      "statistical_rationale": "May distinguish broad calling patterns from repeated calls to a smaller set of contacts, beyond total call volume.",
      "leakage_assessment": "none",
      "business_interpretation": "A narrower or broader calling pattern could help characterize engagement, though it is not itself a causal churn signal."
    },
    {
      "name": "failures_per_use",
      "op": "ratio",
      "inputs": ["Call_Failure", "Frequency_of_use"],
      "semantic_rationale": "Normalizes call failures by usage frequency to estimate failure intensity rather than exposure to calls.",
      "statistical_rationale": "May separate customers with high failure counts due to high usage from those experiencing a high failure rate; check for zero denominators.",
      "leakage_assessment": "none",
      "business_interpretation": "A high value may identify customers who could benefit from network or service-quality investigation."
    },
    {
      "name": "value_per_subscription_unit",
      "op": "ratio",
      "inputs": ["Customer_Value", "Subscription_Length"],
      "semantic_rationale": "Relates customer value to subscription length as a rough value-per-tenure measure.",
      "statistical_rationale": "May distinguish high value driven by longer tenure from high value accumulated over a shorter subscription; check for zero denominators.",
      "leakage_assessment": "possible",
      "business_interpretation": "Could help prioritize retention by value intensity, but the timing and construction of Customer_Value should be verified to ensure it was available before the prediction point."
    },
    {
      "name": "log_customer_value",
      "op": "log1p",
      "inputs": ["Customer_Value"],
      "semantic_rationale": "Transforms customer value while preserving its ordering.",
      "statistical_rationale": "Customer_Value is highly dispersed, so log1p may reduce skew and the influence of extreme values for models sensitive to scale.",
      "leakage_assessment": "possible",
      "business_interpretation": "Makes differences among lower-value customers more distinguishable while retaining information about higher-value customers; verify that the source value is pre-outcome."
    }
  ],
  "candidate_judgements": {
    "cand_seconds_per_call": {
      "decision": "accept",
      "reason": "A seconds-per-call feature derived solely from pre-outcome usage columns can capture typical call duration beyond total usage. Confirm its exact recipe uses no post-outcome fields and handles zero call counts."
    },
    "cand_failure_rate": {
      "decision": "accept",
      "reason": "A failure rate normalized by pre-outcome call activity can distinguish service problems from simply having more calls. Confirm the denominator is an appropriate pre-outcome exposure measure and handle zero denominators."
    },
    "cand_key_log": {
      "decision": "reject",
      "reason": "record_key is a unique identifier, not a defensible customer behavior feature. Its very high association may reflect ordering, label construction, or a split artifact and is unlikely to generalize."
    },
    "cand_post_flag": {
      "decision": "reject",
      "reason": "deactivation_reason is post-outcome information; whether a reason is set directly reveals churn status and would leak the target."
    },
    "cand_friday": {
      "decision": "reject",
      "reason": "load_weekday is identified as a data-loading artifact rather than a customer behavior or reliably available prediction-time signal. Its association is not a sound basis for use."
    },
    "cand_target_mean": {
      "decision": "reject",
      "reason": "The feature is computed using target labels from the full table, including evaluation rows, so it leaks evaluation outcomes. Any target encoding would need to be constructed strictly within training folds with appropriate smoothing."
    }
  }
}

{
  "proposed_features": [
    {
      "name": "seconds_per_call",
      "op": "ratio",
      "inputs": ["Seconds_of_Use", "Frequency_of_use"],
      "semantic_rationale": "Relates total call duration during the observation window to the number of calls.",
      "statistical_rationale": "Captures average call duration, which may distinguish customer usage patterns beyond total usage and call count.",
      "leakage_assessment": "none",
      "business_interpretation": "Higher values indicate longer calls on average; handle zero-call cases explicitly."
    },
    {
      "name": "calls_per_distinct_number",
      "op": "ratio",
      "inputs": ["Frequency_of_use", "Distinct_Called_Numbers"],
      "semantic_rationale": "Relates call volume to the number of distinct numbers contacted.",
      "statistical_rationale": "May capture repeat-calling behavior that is not represented by either count alone.",
      "leakage_assessment": "none",
      "business_interpretation": "Higher values indicate more repeat calls per distinct number; handle zero distinct numbers explicitly."
    },
    {
      "name": "sms_per_call",
      "op": "ratio",
      "inputs": ["Frequency_of_SMS", "Frequency_of_use"],
      "semantic_rationale": "Compares text-message volume with voice-call volume over the same documented observation window.",
      "statistical_rationale": "May capture differences in communication-channel preference beyond the separate usage totals.",
      "leakage_assessment": "none",
      "business_interpretation": "Higher values indicate relatively greater SMS use; handle zero-call cases explicitly."
    },
    {
      "name": "failures_per_call",
      "op": "ratio",
      "inputs": ["Call_Failure", "Frequency_of_use"],
      "semantic_rationale": "Relates call failures to call volume as a measure of failure burden relative to usage.",
      "statistical_rationale": "Normalizes failure counts for usage intensity, potentially distinguishing high-volume customers from customers with unusually many failures for their call volume.",
      "leakage_assessment": "none",
      "business_interpretation": "Higher values indicate more recorded failures relative to calls; this is a proxy, not necessarily a literal failure probability, and zero-call cases need handling."
    },
    {
      "name": "log_seconds_of_use",
      "op": "log1p",
      "inputs": ["Seconds_of_Use"],
      "semantic_rationale": "Transforms total call seconds while retaining the ordering of usage levels.",
      "statistical_rationale": "Can reduce the influence of a long upper tail and make usage differences easier for some models to use.",
      "leakage_assessment": "none",
      "business_interpretation": "Represents call usage on a compressed scale, with smaller relative differences among very high-usage customers."
    },
    {
      "name": "any_call_failure",
      "op": "is_zero",
      "inputs": ["Call_Failure"],
      "semantic_rationale": "Indicates whether the customer had no recorded call failures.",
      "statistical_rationale": "A zero-versus-positive distinction may carry information beyond the count's numeric trend.",
      "leakage_assessment": "none",
      "business_interpretation": "A zero result means at least one call failure was recorded; a nonzero result means none were recorded."
    }
  ],
  "candidate_judgements": {
    "cand_seconds_per_call": {
      "decision": "accept",
      "reason": "A ratio of two documented usage measures from the months 1–9 window can represent average call duration and may add information beyond either total alone. Define behavior for zero calls."
    },
    "cand_failure_rate": {
      "decision": "accept",
      "reason": "A failure-to-call ratio can normalize failures for usage volume and is based on documented observation-window features. Treat it as a proxy rather than a literal probability, and define behavior for zero calls."
    },
    "cand_key_log": {
      "decision": "reject",
      "reason": "record_key is a unique warehouse extraction identifier with exceptionally high target association, not a customer behavior measure. Logging it does not remove the risk of encoding extraction order or other leakage."
    },
    "cand_post_flag": {
      "decision": "reject",
      "reason": "deactivation_reason is recorded in connection with deactivation and is nearly perfectly associated with churn, so it is post-outcome information unavailable at the prediction point."
    },
    "cand_friday": {
      "decision": "reject",
      "reason": "load_weekday describes warehouse loading rather than customer behavior and is identified as an artifact column. Its association may reflect extraction or processing patterns, not a reliable predictive signal."
    },
    "cand_target_mean": {
      "decision": "reject",
      "reason": "The feature uses Churn labels from the full table, including evaluation rows, to construct values. This leaks evaluation outcomes into the feature and would invalidate evaluation."
    }
  }
}

